using System.Collections;
using System.Collections.Generic;
using UnityEngine;

// Line Surf 3D: the web Line Surf (src/components/games/LineSurf.tsx, src/lib/games/line-surf.ts)
// rebuilt as a 30-stage Unity game. There is no freehand stroke: each beat adds one segment of
// the line. Straight adds 1 speed (up to 4), a curve spends 1 and changes lane, a cut drops speed
// to 0. A rock ends the ride, a wave lip needs speed 2, curving off the edge drops you, and so
// does missing the beat. The water is generated by walking one legal line (the web generator,
// same seed mixing) and never storing that line. The 30 stages are fixed seeds; the line grows
// from 8 to 17 segments and the beat tightens from 2.8 s to 1.7 s. Stars from the speed left at
// the end. Buttons, swipes (left / right, down to cut, a tap goes straight) or the arrow keys.
public class LineSurfPlayer : MonoBehaviour
{
    const string Slug = "line-surf";
    const int StageCount = 30, Lanes = 3, LipSpeed = 2, MaxSpeed = 4;
    const float LaneW = 1.6f, ColGap = 3.2f, Glide = 0.32f;

    string U(string en) => OiyoI18n.Ui(en, OiyoArcade.Lang);
    string F(string en, params object[] a) => string.Format(U(en), a);

    public enum GameState { Menu, Ready, Playing, Paused, Victory, GameOver }
    GameState state = GameState.Menu;

    enum Tile { Open, Wall, Lip }
    enum Act { Straight, Left, Right, Cut }
    static readonly string[] ZoneNames = { "Calm bay", "Reef break", "Rock garden", "Big swell", "Storm point", "Night tide" };

    int stageIdx;
    Tile[][] columns;
    int steps, step, lane, speed;
    float fuse, beat, glideT;
    Vector3 fromPos, toPos;
    int score, stars, bestFinish;
    string endReason = "";
    string popup = ""; float popupTimer; Color popupColor;
    bool fell;

    Camera cam;
    Transform root, surfer, board, rider;
    Material seaMat;
    Bursts bursts;
    Synth synth;
    bool showStages;
    float shake, seaScroll, swell;
    readonly List<Transform> lips = new List<Transform>();
    TrailRenderer wake;

    int StepsOf(int i) => 8 + i / 3;
    float BeatOf(int i) => Mathf.Lerp(2.8f, 1.7f, i / (float)(StageCount - 1));
    uint SeedOf(int i) => (uint)(20261123 + i * 7919);

    void Awake()
    {
        Application.targetFrameRate = 60;
        SetupScene();
        stageIdx = Mathf.Clamp(OiyoArcade.Unlocked(Slug) - 1, 0, StageCount - 1);
        LoadStage(stageIdx, false);
    }

    void SetupScene()
    {
        cam = new GameObject("Camera").AddComponent<Camera>();
        cam.fieldOfView = 55f;
        cam.clearFlags = CameraClearFlags.SolidColor;
        cam.backgroundColor = new Color(0.1f, 0.15f, 0.3f);
        cam.farClipPlane = 200f;
        var key = new GameObject("Key").AddComponent<Light>();
        key.type = LightType.Directional;
        key.intensity = 1.05f;
        key.color = new Color(1f, 0.88f, 0.72f);
        key.transform.rotation = Quaternion.Euler(30f, -25f, 0f);
        RenderSettings.ambientMode = UnityEngine.Rendering.AmbientMode.Flat;
        RenderSettings.ambientLight = new Color(0.45f, 0.5f, 0.62f);
        seaMat = OiyoArcade.Lit(Color.white, 0.8f, OiyoArcade.Art("LS/sea", true));
        bursts = new Bursts(transform, 1.2f);
        synth = new Synth(gameObject);
    }

    // ---------------- Course (port of createPuzzle in src/lib/games/line-surf.ts) ----------------
    static System.Func<float> Mulberry(uint s)
    {
        uint a = s;
        return () =>
        {
            a += 0x6d2b79f5u;
            uint t = a;
            t = (t ^ (t >> 15)) * (t | 1u);
            t ^= t + (t ^ (t >> 7)) * (t | 61u);
            return (t ^ (t >> 14)) / 4294967296f;
        };
    }

    static bool Moved(int l, int sp, Act act, out int nl, out int ns)
    {
        nl = l; ns = sp;
        switch (act)
        {
            case Act.Straight: ns = Mathf.Min(MaxSpeed, sp + 1); return true;
            case Act.Cut: ns = 0; return true;
            case Act.Left: if (l == 0) return false; nl = l - 1; ns = Mathf.Max(0, sp - 1); return true;
            default: if (l == Lanes - 1) return false; nl = l + 1; ns = Mathf.Max(0, sp - 1); return true;
        }
    }

    static Act ForcedAct(int l, int st, System.Func<float> rng)
    {
        if (st % 3 == 2)
        {
            if (l == 0) return Act.Right;
            if (l == 2) return Act.Left;
            return rng() < 0.5f ? Act.Left : Act.Right;
        }
        var choices = new List<Act> { Act.Straight };
        if (l > 0) choices.Add(Act.Left);
        if (l < Lanes - 1) choices.Add(Act.Right);
        return choices[Mathf.Min(choices.Count - 1, Mathf.FloorToInt(rng() * choices.Count))];
    }

    static Tile[][] CreateCourse(uint seed, int count)
    {
        var rng = Mulberry(seed ^ 0x51a70001u);
        int l = 1, sp = 2;
        var cols = new Tile[count][];
        for (int st = 0; st < count; st++)
        {
            var tiles = new[] { Tile.Open, Tile.Open, Tile.Open };
            var act = ForcedAct(l, st, rng);
            if (!Moved(l, sp, act, out int nl, out int ns)) { cols[st] = tiles; continue; }
            if (act == Act.Left || act == Act.Right) tiles[l] = Tile.Wall;
            if (ns >= LipSpeed && rng() < 0.5f) tiles[nl] = Tile.Lip;
            var others = new List<int>();
            for (int k = 0; k < Lanes; k++) if (k != nl && tiles[k] == Tile.Open) others.Add(k);
            if (others.Count > 0 && rng() < 0.75f) tiles[others[Mathf.Min(others.Count - 1, Mathf.FloorToInt(rng() * others.Count))]] = Tile.Wall;
            if (tiles[nl] == Tile.Wall || (tiles[nl] == Tile.Lip && ns < LipSpeed)) tiles[nl] = Tile.Open;
            cols[st] = tiles;
            l = nl; sp = ns;
        }
        return cols;
    }

    // Highest speed any legal line can still have at the end (stars are measured against it:
    // some waters force a slow finish).
    static int BestFinish(Tile[][] cols)
    {
        var states = new HashSet<int> { 1 * 8 + 2 };
        foreach (var col in cols)
        {
            var next = new HashSet<int>();
            foreach (int st in states)
                foreach (Act a in System.Enum.GetValues(typeof(Act)))
                {
                    if (!Moved(st / 8, st % 8, a, out int nl, out int ns)) continue;
                    if (col[nl] == Tile.Wall || (col[nl] == Tile.Lip && ns < LipSpeed)) continue;
                    next.Add(nl * 8 + ns);
                }
            states = next;
        }
        int best = 0;
        foreach (int st in states) best = Mathf.Max(best, st % 8);
        return best;
    }

    // ---------------- Scene ----------------
    static Vector3 Spot(int ln, int at) => new Vector3((ln - 1) * LaneW, 0f, at * ColGap);

    void BuildCourse()
    {
        var horizon = OiyoArcade.Prim(PrimitiveType.Quad, "Horizon", OiyoArcade.Textured(OiyoArcade.Art("LS/horizon")), root);
        horizon.transform.position = new Vector3(0f, 12f, steps * ColGap + 70f);
        horizon.transform.localScale = new Vector3(190f, 95f, 1f);
        var sea = OiyoArcade.Prim(PrimitiveType.Quad, "Sea", seaMat, root);
        sea.transform.rotation = Quaternion.Euler(90f, 0f, 0f);
        sea.transform.position = new Vector3(0f, -0.02f, steps * ColGap * 0.5f + 20f);
        sea.transform.localScale = new Vector3(120f, steps * ColGap + 140f, 1f);
        seaMat.mainTextureScale = new Vector2(20f, (steps * ColGap + 140f) / 6f);
        // lane seams: faint foam lines between the three lanes
        var seamMat = OiyoArcade.Transparent(OiyoArcade.GlowTexture(), new Color(0.85f, 0.97f, 1f, 0.35f));
        for (int k = 0; k < 2; k++)
        {
            var seam = OiyoArcade.Prim(PrimitiveType.Quad, "Seam", seamMat, root);
            seam.transform.rotation = Quaternion.Euler(90f, 0f, 0f);
            seam.transform.position = new Vector3((k - 0.5f) * LaneW, 0.01f, (steps + 1) * ColGap * 0.5f);
            seam.transform.localScale = new Vector3(0.12f, (steps + 1) * ColGap, 1f);
        }
        var rockMat = OiyoArcade.Lit(Color.white, 0.25f, OiyoArcade.Art("LS/rock", true));
        var lipMat = OiyoArcade.Lit(new Color(0.2f, 0.65f, 0.85f), 0.85f);
        var capMat = OiyoArcade.Lit(new Color(0.92f, 0.98f, 1f), 0.6f);
        lips.Clear();
        for (int c = 0; c < steps; c++)
        {
            for (int ln = 0; ln < Lanes; ln++)
            {
                var at = Spot(ln, c + 1);
                var tile = columns[c][ln];
                if (tile == Tile.Wall)
                {
                    var rock = OiyoArcade.Prim(PrimitiveType.Sphere, "Rock", rockMat, root);
                    rock.transform.position = at + new Vector3(0f, 0.25f, 0f);
                    rock.transform.localScale = new Vector3(1.25f, 0.95f + ((c * 7 + ln * 3) % 5) * 0.08f, 1.1f);
                    rock.transform.rotation = Quaternion.Euler((c * 37 + ln * 11) % 30, (c * 53 + ln * 29) % 360, 0f);
                    var spray = OiyoArcade.GlowQuad("Foam", new Color(1f, 1f, 1f, 0.55f), 1.9f, root);
                    spray.transform.SetPositionAndRotation(at + Vector3.up * 0.03f, Quaternion.Euler(90f, 0f, 0f));
                }
                else if (tile == Tile.Lip)
                {
                    var lip = new GameObject("Lip").transform;
                    lip.SetParent(root, false);
                    lip.position = at;
                    // a rounded swell with a curling white crest
                    var body = OiyoArcade.Prim(PrimitiveType.Sphere, "Swell", lipMat, lip);
                    body.transform.localScale = new Vector3(LaneW * 0.95f, 0.7f, 1.5f);
                    body.transform.localPosition = new Vector3(0f, 0f, 0f);
                    var cap = OiyoArcade.Prim(PrimitiveType.Sphere, "Crest", capMat, lip);
                    cap.transform.localScale = new Vector3(LaneW * 0.85f, 0.22f, 0.5f);
                    cap.transform.localPosition = new Vector3(0f, 0.3f, 0.22f);
                    var foam = OiyoArcade.GlowQuad("Foam", new Color(1f, 1f, 1f, 0.5f), 1.6f, lip);
                    foam.transform.localPosition = new Vector3(0f, 0.36f, 0.25f);
                    lips.Add(lip);
                }
            }
        }
        // the finish: two buoys and a banner of glow across the line's end
        var finish = Spot(1, steps + 1);
        var buoyMat = OiyoArcade.Lit(new Color(1f, 0.45f, 0.2f), 0.6f);
        for (int s = -1; s <= 1; s += 2)
        {
            var b = OiyoArcade.Prim(PrimitiveType.Sphere, "Buoy", buoyMat, root);
            b.transform.position = finish + new Vector3(s * (LaneW * 1.7f), 0.3f, 0f);
            b.transform.localScale = new Vector3(0.6f, 0.75f, 0.6f);
            OiyoArcade.GlowQuad("Glow", new Color(1f, 0.7f, 0.3f, 0.6f), 1.8f, root).transform.position = b.transform.position + Vector3.up * 0.5f;
        }
        var line = OiyoArcade.Prim(PrimitiveType.Cube, "FinishLine", OiyoArcade.Glow(new Color(1f, 0.9f, 0.5f)), root);
        line.transform.position = finish + new Vector3(0f, 0.02f, 0f);
        line.transform.localScale = new Vector3(LaneW * 3.4f, 0.02f, 0.12f);

        surfer = new GameObject("Surfer").transform;
        surfer.SetParent(root, false);
        board = OiyoArcade.Prim(PrimitiveType.Capsule, "Board", OiyoArcade.Lit(new Color(1f, 0.85f, 0.3f), 0.7f), surfer).transform;
        board.localRotation = Quaternion.Euler(90f, 0f, 0f);
        board.localScale = new Vector3(0.42f, 0.7f, 0.08f);
        board.localPosition = new Vector3(0f, 0.06f, 0f);
        rider = new GameObject("Rider").transform;
        rider.SetParent(surfer, false);
        var suit = OiyoArcade.Lit(new Color(0.15f, 0.2f, 0.35f), 0.4f);
        var legs = OiyoArcade.Prim(PrimitiveType.Capsule, "Legs", suit, rider);
        legs.transform.localPosition = new Vector3(0f, 0.42f, 0f);
        legs.transform.localScale = new Vector3(0.26f, 0.3f, 0.2f);
        var torso = OiyoArcade.Prim(PrimitiveType.Capsule, "Torso", OiyoArcade.Lit(new Color(0.95f, 0.3f, 0.35f), 0.4f), rider);
        torso.transform.localPosition = new Vector3(0f, 0.85f, 0.04f);
        torso.transform.localScale = new Vector3(0.3f, 0.26f, 0.22f);
        var head = OiyoArcade.Prim(PrimitiveType.Sphere, "Head", OiyoArcade.Lit(new Color(0.95f, 0.78f, 0.62f), 0.3f), rider);
        head.transform.localPosition = new Vector3(0f, 1.2f, 0.06f);
        head.transform.localScale = Vector3.one * 0.24f;
        var arms = OiyoArcade.Prim(PrimitiveType.Cube, "Arms", OiyoArcade.Lit(new Color(0.95f, 0.3f, 0.35f), 0.4f), rider);
        arms.transform.localPosition = new Vector3(0f, 0.92f, 0.04f);
        arms.transform.localScale = new Vector3(0.9f, 0.07f, 0.08f);
        wake = surfer.gameObject.AddComponent<TrailRenderer>();
        wake.time = 0.9f;
        wake.startWidth = 0.45f;
        wake.endWidth = 0.05f;
        wake.sharedMaterial = OiyoArcade.Transparent(OiyoArcade.GlowTexture(), new Color(1f, 1f, 1f, 0.55f));
        wake.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
    }

    void LoadStage(int idx, bool ready = true)
    {
        stageIdx = Mathf.Clamp(idx, 0, StageCount - 1);
        if (root != null) Destroy(root.gameObject);
        root = new GameObject("Course").transform;
        steps = StepsOf(stageIdx);
        columns = CreateCourse(SeedOf(stageIdx), steps);
        bestFinish = BestFinish(columns);
        BuildCourse();
        step = 0; lane = 1; speed = 2;
        beat = BeatOf(stageIdx);
        fuse = beat;
        glideT = 1f;
        fromPos = toPos = Spot(lane, 0);
        surfer.position = toPos;
        if (wake != null) wake.Clear();
        fell = false;
        score = stars = 0;
        endReason = ""; popup = "";
        showStages = false;
        state = ready ? GameState.Ready : GameState.Menu;
    }

    // ---------------- Loop ----------------
    void Update()
    {
        // Run result for the embedding OIYO page (scripts/unity/oiyo-result).
        OiyoResult.Track("line-surf", state, score);
        float dt = Time.deltaTime;
        ReadInput();
        if (state == GameState.Playing)
        {
            fuse -= dt;
            if (fuse <= 0f) Expire();
            else if (fuse < 0.9f && Mathf.FloorToInt((fuse + dt) * 3f) != Mathf.FloorToInt(fuse * 3f)) synth.Tone(1200f, 0.04f, Wave.Square, 0.08f, 0f, 40f);
        }
        Animate(dt);
        UpdateCamera(dt);
    }

    bool tracking; Vector2 swipeStart; int swipeId;
    void ReadInput()
    {
        bool confirm = Input.GetKeyDown(KeyCode.Space) || Input.GetKeyDown(KeyCode.Return);
        Act? act = null;
        if (Input.GetKeyDown(KeyCode.LeftArrow) || Input.GetKeyDown(KeyCode.A)) act = Act.Left;
        else if (Input.GetKeyDown(KeyCode.RightArrow) || Input.GetKeyDown(KeyCode.D)) act = Act.Right;
        else if (Input.GetKeyDown(KeyCode.UpArrow) || Input.GetKeyDown(KeyCode.W) || Input.GetKeyDown(KeyCode.Space)) act = Act.Straight;
        else if (Input.GetKeyDown(KeyCode.DownArrow) || Input.GetKeyDown(KeyCode.S) || Input.GetKeyDown(KeyCode.C)) act = Act.Cut;
        // swipes on the water: left/right curve, down cuts, a tap goes straight
        if (state == GameState.Ready || state == GameState.Playing)
        {
            foreach (var p in OiyoArcade.Began()) { tracking = true; swipeStart = p.pos; swipeId = p.id; }
            foreach (var p in OiyoArcade.Ended())
            {
                if (!tracking || p.id != swipeId) continue;
                tracking = false;
                var d = p.pos - swipeStart;
                float min = Mathf.Min(Screen.width, Screen.height) * 0.07f;
                if (d.magnitude < min) act = Act.Straight;
                else if (Mathf.Abs(d.x) > Mathf.Abs(d.y)) act = d.x < 0f ? Act.Left : Act.Right;
                else act = d.y < 0f ? Act.Cut : Act.Straight;
            }
        }
        switch (state)
        {
            case GameState.Ready:
                // the first stroke both starts the ride and is played
                if (act.HasValue) { state = GameState.Playing; Ride(act.Value); }
                return;
            case GameState.Playing:
                if (Input.GetKeyDown(KeyCode.Escape) || Input.GetKeyDown(KeyCode.P)) { state = GameState.Paused; return; }
                if (act.HasValue) Ride(act.Value);
                return;
            case GameState.Paused:
                if (Input.GetKeyDown(KeyCode.Escape) || Input.GetKeyDown(KeyCode.P)) state = GameState.Playing;
                return;
            case GameState.Victory:
            case GameState.GameOver:
                if (confirm) LoadStage(state == GameState.Victory ? Mathf.Min(stageIdx + 1, StageCount - 1) : stageIdx);
                return;
            case GameState.Menu:
                if (!showStages && confirm) LoadStage(stageIdx);
                return;
        }
    }

    void Ride(Act act)
    {
        if (state != GameState.Playing) return;
        int before = speed;
        if (!Moved(lane, speed, act, out int nl, out int ns))
        {
            // curving off the edge of the water
            fromPos = surfer.position; toPos = Spot(lane, step) + new Vector3((act == Act.Left ? -1f : 1f) * LaneW * 1.2f, 0f, ColGap * 0.5f);
            glideT = 0f;
            Lose(U("You curved off the edge of the water."));
            return;
        }
        var tile = columns[step][nl];
        fromPos = surfer.position; toPos = Spot(nl, step + 1); glideT = 0f;
        lane = nl; speed = ns;
        if (tile == Tile.Wall) { toPos -= new Vector3(0f, 0f, 0.9f); Lose(U("The line met a rock.")); return; }
        if (tile == Tile.Lip && ns < LipSpeed) { toPos -= new Vector3(0f, 0f, 0.6f); Lose(F("A lip needs speed {0}.", LipSpeed)); return; }
        step++;
        fuse = beat;
        score += 50 + speed * 25 + (tile == Tile.Lip ? 120 : 0);
        // cues: straight, curve, cut and lip each sound different
        if (tile == Tile.Lip) { synth.Tone(520f, 0.25f, Wave.Triangle, 0.25f, 1040f, 6f); Popup(U("Over the lip!"), new Color(0.6f, 0.95f, 1f)); }
        else if (act == Act.Cut) synth.Tone(240f, 0.16f, Wave.Noise, 0.2f, 0f, 12f);
        else if (act == Act.Straight) synth.Tone(440f + speed * 80f, 0.1f, Wave.Sine, 0.22f, 0f, 12f);
        else synth.Tone(380f, 0.12f, Wave.Triangle, 0.2f, 300f, 10f);
        bursts.Emit(fromPos + Vector3.up * 0.1f, new Color(0.85f, 0.97f, 1f), 6 + speed * 3, 1.5f + speed * 0.6f, 0.18f, 0.5f, Vector3.up * 2f);
        if (step >= steps) Win();
    }

    void Expire()
    {
        if (state != GameState.Playing) return;
        fromPos = surfer.position; toPos = surfer.position + Vector3.forward * 0.6f; glideT = 0f;
        Lose(U("You missed the beat."));
    }

    void Lose(string why)
    {
        endReason = why;
        fell = true;
        state = GameState.GameOver;
        shake = 0.3f;
        bursts.Emit(toPos + Vector3.up * 0.2f, Color.white, 40, 4f, 0.25f, 0.8f, Vector3.up * 2f);
        synth.Tone(200f, 0.45f, Wave.Saw, 0.25f, 80f, 4f);
        synth.Tone(120f, 0.4f, Wave.Noise, 0.2f, 0f, 6f);
    }

    void Win()
    {
        stars = speed >= bestFinish ? 3 : speed >= bestFinish - 1 ? 2 : 1;
        score += speed * 150 + stageIdx * 10;
        state = GameState.Victory;
        OiyoArcade.Record(Slug, stageIdx, stars, score, StageCount);
        StartCoroutine(Arp(new[] { 523f, 659f, 784f, 1047f, 1319f }, 0.09f));
    }

    void Popup(string t, Color c) { popup = t; popupColor = c; popupTimer = 0.9f; }

    IEnumerator Arp(float[] fs, float gap)
    {
        foreach (var f in fs) { synth.Tone(f, 0.2f, Wave.Triangle, 0.3f, 0f, 6f); yield return new WaitForSeconds(gap); }
    }

    // ---------------- View ----------------
    void Animate(float dt)
    {
        popupTimer -= dt;
        swell += dt;
        seaScroll += dt * 0.05f;
        seaMat.mainTextureOffset = new Vector2(Mathf.Sin(swell * 0.3f) * 0.05f, seaScroll);
        if (surfer == null) return;
        glideT = Mathf.Min(1f, glideT + dt / Glide);
        float e = 1f - (1f - glideT) * (1f - glideT);
        var p = Vector3.Lerp(fromPos, toPos, e);
        bool overLip = !fell && step > 0 && step <= steps && columns[step - 1][lane] == Tile.Lip && glideT < 1f;
        p.y = overLip ? Mathf.Sin(glideT * Mathf.PI) * 0.7f : Mathf.Sin(swell * 2.2f) * 0.04f;
        surfer.position = p;
        float lean = (toPos.x - fromPos.x) * (1f - e) * -18f;
        if (fell)
        {
            float f = Mathf.Clamp01(glideT * 1.4f);
            rider.localRotation = Quaternion.Euler(70f * f, 0f, 30f * f);
            rider.localPosition = new Vector3(0f, -0.4f * f, 0.3f * f);
        }
        else
        {
            float crouch = speed * 4f;
            rider.localRotation = Quaternion.Euler(crouch, 0f, lean);
            rider.localPosition = Vector3.zero;
        }
        surfer.rotation = Quaternion.Euler(0f, (toPos.x - fromPos.x) * (1f - e) * 25f, 0f);
        if (wake != null) wake.emitting = speed > 0 && !fell;
        for (int i = 0; i < lips.Count; i++)
            lips[i].localScale = new Vector3(1f, 1f + Mathf.Sin(swell * 2.5f + i) * 0.08f, 1f);
    }

    void UpdateCamera(float dt)
    {
        float aspect = cam.aspect;
        // far enough back that the three lanes fit the width on a phone
        float back = aspect < 1f ? 5.6f / Mathf.Max(0.45f, aspect) * 0.62f : 5.2f;
        var focus = surfer != null ? new Vector3(surfer.position.x * 0.35f, 0f, surfer.position.z) : Vector3.zero;
        if (state == GameState.Menu) focus = new Vector3(0f, 0f, Mathf.PingPong(Time.time * 1.2f, steps * ColGap * 0.6f));
        var want = focus + new Vector3(0f, back * 0.62f, -back);
        cam.transform.position = dt <= 0f ? want : Vector3.Lerp(cam.transform.position, want, 1f - Mathf.Exp(-dt * 6f));
        if (shake > 0f) { cam.transform.position += Random.insideUnitSphere * shake * 0.2f; shake = Mathf.MoveTowards(shake, 0f, dt); }
        cam.transform.rotation = Quaternion.LookRotation(focus + new Vector3(0f, 0.2f, back * 0.95f) - cam.transform.position);
    }

    // ---------------- GUI ----------------
    static readonly Color Accent = new Color(0.1f, 0.6f, 0.75f, 0.97f);
    static readonly Color Dark = new Color(0.03f, 0.08f, 0.14f, 0.84f);
    static readonly Color Gold = new Color(1f, 0.8f, 0.25f, 0.97f);
    static readonly Color Slate = new Color(0.16f, 0.25f, 0.34f, 0.95f);

    string StageTitle(int i) => F("Stage {0}", i + 1) + " · " + U(ZoneNames[i / 5]);

    void OnGUI()
    {
        OiyoArcade.Begin();
        float w = OiyoArcade.W, h = OiyoArcade.H;
        if (state == GameState.Menu) { DrawMenu(w, h); return; }
        var bar = new Rect(8f, 8f, w - 16f, 58f);
        OiyoArcade.Panel(bar, Dark);
        OiyoArcade.Text(new Rect(20f, 12f, w - 140f, 24f), "<b>" + StageTitle(stageIdx) + "</b>", 16, new Color(0.7f, 0.95f, 1f));
        string pips = "";
        for (int i = 0; i < MaxSpeed; i++) pips += i < speed ? "<color=#ffd54a>●</color>" : "<color=#ffffff33>●</color>";
        OiyoArcade.Text(new Rect(20f, 36f, w - 140f, 24f), $"{U("Speed")} {pips}   {U("Line")} <b>{Mathf.Min(step, steps)}/{steps}</b>   {U("Score")} <b>{score}</b>", 14, Color.white);
        if (OiyoArcade.Button(new Rect(w - 64f, 14f, 46f, 46f), "<b>II</b>", Slate, 18))
        {
            if (state == GameState.Playing) state = GameState.Paused;
            else if (state == GameState.Ready) state = GameState.Menu;
        }
        if (state == GameState.Playing || state == GameState.Ready)
        {
            float t = state == GameState.Ready ? 1f : Mathf.Clamp01(fuse / beat);
            OiyoArcade.Bar(new Rect(16f, 70f, w - 32f, 8f), t, new Color(0f, 0f, 0f, 0.4f), Color.Lerp(new Color(1f, 0.35f, 0.3f), new Color(0.4f, 0.95f, 1f), t));
            OiyoArcade.Text(new Rect(16f, 80f, w - 32f, 18f), U("Beat"), 12, new Color(1f, 1f, 1f, 0.7f));
            DrawControls(w, h);
        }
        if (popupTimer > 0f && state == GameState.Playing)
            OiyoArcade.Shadowed(new Rect(0f, h * 0.3f, w, 40f), popup, Mathf.RoundToInt(22 + popupTimer * 10f), popupColor, TextAnchor.MiddleCenter);
        if (state == GameState.Ready)
        {
            var r = new Rect(w * 0.5f - 175f, 104f, 350f, 120f);
            OiyoArcade.Panel(r, Dark);
            OiyoArcade.Text(new Rect(r.x + 12f, r.y + 8f, r.width - 24f, r.height - 16f),
                $"<b>{U("One stroke per beat")}</b>\n<size=13>{U("Straight +1 speed, a curve -1 and a lane over, a cut stops. Rocks end the ride; a lip needs speed 2.")}</size>", 16, Color.white, TextAnchor.MiddleCenter);
        }
        if (state == GameState.Paused) DrawPause(w, h);
        if (state == GameState.Victory || state == GameState.GameOver) DrawResult(w, h);
    }

    void DrawControls(float w, float h)
    {
        float bw = Mathf.Min(86f, (w - 40f) / 4f), gap = 8f, bh = 64f;
        float total = bw * 4f + gap * 3f, x = w * 0.5f - total * 0.5f, y = h - bh - 14f;
        var c = new Color(0.08f, 0.2f, 0.3f, 0.88f);
        if (OiyoArcade.Button(new Rect(x, y, bw, bh), "◀\n<size=12>" + U("Left") + "</size>", c, 20)) Press(Act.Left);
        if (OiyoArcade.Button(new Rect(x + (bw + gap), y, bw, bh), "▲\n<size=12>" + U("Straight") + "</size>", new Color(0.12f, 0.55f, 0.72f, 0.95f), 20)) Press(Act.Straight);
        if (OiyoArcade.Button(new Rect(x + (bw + gap) * 2f, y, bw, bh), "■\n<size=12>" + U("Cut") + "</size>", c, 20)) Press(Act.Cut);
        if (OiyoArcade.Button(new Rect(x + (bw + gap) * 3f, y, bw, bh), "▶\n<size=12>" + U("Right") + "</size>", c, 20)) Press(Act.Right);
    }

    void Press(Act a)
    {
        tracking = false;
        if (state == GameState.Ready) state = GameState.Playing;
        Ride(a);
    }

    void DrawMenu(float w, float h)
    {
        if (showStages)
        {
            float bw = Mathf.Min(w - 16f, 760f);
            var box = new Rect(w * 0.5f - bw * 0.5f, 12f, bw, h - 24f);
            OiyoArcade.Panel(box, new Color(0.03f, 0.08f, 0.14f, 0.94f));
            OiyoArcade.Text(new Rect(box.x + 16f, box.y + 12f, box.width - 120f, 30f), "<b>" + U("Choose a stage") + "</b>", 20, Color.white);
            OiyoArcade.Text(new Rect(box.x + 16f, box.y + 40f, box.width - 32f, 22f), $"★ {OiyoArcade.TotalStars(Slug, StageCount)}/{StageCount * 3}", 15, Gold);
            if (OiyoArcade.Button(new Rect(box.xMax - 100f, box.y + 12f, 86f, 40f), U("Back"), Slate, 16)) showStages = false;
            int pick = OiyoArcade.StageGrid(new Rect(box.x + 14f, box.y + 70f, box.width - 28f, box.height - 84f), Slug, StageCount, Accent, U("Stage"));
            if (pick >= 0) LoadStage(pick);
            return;
        }
        float cw = Mathf.Min(380f, w - 24f);
        var card = new Rect(w * 0.5f - cw * 0.5f, h * 0.5f - 170f, cw, 340f);
        OiyoArcade.Panel(card, Dark);
        OiyoArcade.Shadowed(new Rect(card.x, card.y + 18f, cw, 40f), U("Line Surf 3D"), 30, new Color(0.7f, 0.95f, 1f), TextAnchor.MiddleCenter);
        OiyoArcade.Text(new Rect(card.x + 20f, card.y + 62f, cw - 40f, 46f), U("One stroke is the track. Straight adds speed, a curve spends it, a cut empties it."), 15, new Color(1f, 1f, 1f, 0.85f), TextAnchor.MiddleCenter);
        OiyoArcade.Text(new Rect(card.x, card.y + 110f, cw, 24f), StageTitle(stageIdx), 15, Gold, TextAnchor.MiddleCenter);
        if (OiyoArcade.Button(new Rect(card.x + 24f, card.y + 142f, cw - 48f, 58f), "<b>▶ " + F("Play stage {0}", stageIdx + 1) + "</b>", Accent, 21)) LoadStage(stageIdx);
        if (OiyoArcade.Button(new Rect(card.x + 24f, card.y + 210f, cw - 48f, 46f), U("All 30 stages") + $"  ★ {OiyoArcade.TotalStars(Slug, StageCount)}", Slate, 17)) showStages = true;
        if (OiyoArcade.Button(new Rect(card.x + 24f, card.y + 266f, cw - 48f, 46f), "Aa  " + OiyoArcade.Lang.ToUpperInvariant(), Slate, 17)) OiyoArcade.NextLang();
    }

    void DrawPause(float w, float h)
    {
        float cw = Mathf.Min(340f, w - 24f);
        var card = new Rect(w * 0.5f - cw * 0.5f, h * 0.5f - 130f, cw, 260f);
        OiyoArcade.Panel(card, Dark);
        OiyoArcade.Shadowed(new Rect(card.x, card.y + 16f, cw, 36f), U("Paused"), 26, Color.white, TextAnchor.MiddleCenter);
        if (OiyoArcade.Button(new Rect(card.x + 24f, card.y + 70f, cw - 48f, 52f), "▶ " + U("Resume"), Accent, 19)) state = GameState.Playing;
        if (OiyoArcade.Button(new Rect(card.x + 24f, card.y + 132f, cw - 48f, 46f), U("Restart"), Slate, 17)) LoadStage(stageIdx);
        if (OiyoArcade.Button(new Rect(card.x + 24f, card.y + 188f, cw - 48f, 46f), U("Stage list"), Slate, 17)) { LoadStage(stageIdx, false); showStages = true; }
    }

    void DrawResult(float w, float h)
    {
        bool won = state == GameState.Victory;
        float cw = Mathf.Min(360f, w - 24f);
        float ch = 158f + (won ? 58f : 0f) + 52f + 40f + 18f;
        var card = new Rect(w * 0.5f - cw * 0.5f, h * 0.5f - ch * 0.5f, cw, ch);
        OiyoArcade.Panel(card, Dark);
        OiyoArcade.Shadowed(new Rect(card.x, card.y + 14f, cw, 38f), won ? U("Stage clear!") : U("Game over"), 28, won ? new Color(0.6f, 1f, 0.65f) : new Color(1f, 0.55f, 0.5f), TextAnchor.MiddleCenter);
        string detail = won ? $"<size=30>{OiyoArcade.StarString(stars)}</size>" : endReason;
        OiyoArcade.Text(new Rect(card.x + 16f, card.y + 56f, cw - 32f, 44f), detail, 16, Color.white, TextAnchor.MiddleCenter);
        OiyoArcade.Text(new Rect(card.x + 16f, card.y + 100f, cw - 32f, 48f),
            $"{U("Score")} <b>{score}</b>   {U("Line")} <b>{step}/{steps}</b>\n<size=14>{(won ? F("Speed {0} left at the end", speed) + " · " + F("best possible {0}", bestFinish) : "")}</size>", 16, Color.white, TextAnchor.MiddleCenter);
        float y = card.y + 158f;
        if (won && stageIdx < StageCount - 1)
        {
            if (OiyoArcade.Button(new Rect(card.x + 24f, y, cw - 48f, 50f), "<b>" + U("Next stage") + " ▶</b>", Accent, 19)) LoadStage(stageIdx + 1);
            y += 58f;
        }
        else if (won)
        {
            OiyoArcade.Text(new Rect(card.x, y, cw, 50f), "★ " + U("You cleared all 30 stages!") + " ★", 17, Gold, TextAnchor.MiddleCenter);
            y += 58f;
        }
        if (OiyoArcade.Button(new Rect(card.x + 24f, y, cw - 48f, 44f), U("Retry"), won ? Slate : Accent, 17)) LoadStage(stageIdx);
        y += 52f;
        if (OiyoArcade.Button(new Rect(card.x + 24f, y, cw - 48f, 40f), U("Stage list"), Slate, 16)) { LoadStage(stageIdx, false); showStages = true; }
    }
}
